#!/bin/sh
# One kith-pkg line. $1 changes the agents first (- for nothing); the rest is the line, which Python's kith-pkg answers on
# the OLD side and `kith kernel pkg` on the NEW side. Edits are made by the script so each side's own folders change.
ops=$1; shift
A=$KITH_HOME/agents
S=$KITH_STATE/store
for op in $(echo "$ops" | tr ',' ' '); do
case $op in
  -) ;;
  notes) echo more >> "$A/echo/role/notes.md" ;;
  break) printf -- '---\nname: echo\n---\nno description\n' > "$A/echo/role/agent.md" ;;
  fix) printf -- '---\nname: echo\ndescription: test agent\n---\nYou echo.\n' > "$A/echo/role/agent.md" ;;
  editing) touch "$A/echo/role/.editing" ;;
  editing-old) touch -t 202001010000 "$A/echo/role/.editing" ;;
  editing-beta) touch "$A/beta/role/.editing" ;;
  pin-good) cp "$S/.pointers/echo.good" "$S/.pointers/echo.pin" ;;
  pin-missing) echo feedface00x > "$S/.pointers/echo.pin" ;;
  unpin) rm -f "$S/.pointers/echo.pin" ;;
  gc-fixture)
    now=$(date +%s)
    for i in 1 2 3 4 5; do mkdir -p "$S/echo@old$i"; printf '{"agent": "echo", "made": %s.5}' $((<fingerprint> + i)) > "$S/echo@old$i/.meta.json"; done
    mkdir -p "$S/echo@rec1" "$S/echo@rec2" "$S/echo@rec3"
    printf '{"made": %s}' $((now - 100000)) > "$S/echo@rec1/.meta.json"
    printf '{"made": %s}' $((now - 150000)) > "$S/echo@rec2/.meta.json"
    printf '{"made": %s}' $((now - 200000)) > "$S/echo@rec3/.meta.json"
    mkdir -p "$S/echo@old3/.runs" "$S/echo@old2/.runs" "$S/echo@old4/.runs"
    : > "$S/echo@old3/.runs/1.live"; : > "$S/echo@old3/.runs/999999.dead"; : > "$S/echo@old3/.runs/notapid.x"
    : > "$S/echo@old2/.runs/999999.dead"
    : > "$S/echo@old4/.runs/1.live"
    ;;
  *) echo "w.sh: unknown change $op" >&2; exit 99 ;;
esac
done
if [ "$KITH_CORE" = rust ]; then "$KITH_BIN" kernel pkg --kernel "$HOME/k" "$@"; else "$HOME/k/bin/kith-pkg" "$@"; fi
rc=$?
# what the store holds after this line, versions counted (their names carry a hash that differs per side)
echo "store: $(ls -A "$S" 2>/dev/null | sed -E 's/@[0-9a-f]{10}$/@V/' | sort | uniq -c | sed -E 's/^ +//' | tr '\n' ';')" >> "$DIFFTEST_FAKELOG"
exit $rc

